// AUTO-GENERATED by scripts/story-audio/story-clips.mjs — do not edit by hand. Regenerate with: npm run stories:clips

export const STORY_CLIPS = [
  {"id":"dbu.storyteller.c252259c","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Three nights ago the storm took the Long Bridge. Luma is two towns now — one on each side of the Ashgill gorge — and between them hangs a single iron cable and a basket that only crosses if both banks pull."},
  {"id":"dbu.storyteller.664f9564","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Your side has the winter oil and the last good rope. It also has Hollis, who kept the bridge for forty years, and a gash in his leg from the storm that is starting to smell wrong."},
  {"id":"dbu.hollis.0a431887","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Fever-bark, that’s what this wants. Comes up the west road from Varn."},
  {"id":"dbu.hollis.15030883","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"The west road is over there."},
  {"id":"dbu.storyteller.f27aab83","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"A lantern on the far cliff. A courier in a long coat, amber scarf pulled up against the wind, studying the cable the way you are."},
  {"id":"dbu.mira.1ff77435","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"You the new keeper? Hollis finally let someone else touch his winch?"},
  {"id":"dbu.mira.d3d625f8","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I’m Mira. I carry for the high villages. I’ve got something in this pack someone over there probably needs, and you’ve probably got something I need. Hard to tell from here."},
  {"id":"dbu.storyteller.afea70ae","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"She waits, lantern raised. What do you tell her?"},
  {"id":"dbu.mira.71966100","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Fever-bark. I’ve got a bundle from Varn, meant for Orrin’s Rest — the high hamlet. My brother Tav’s up there with the flocks."},
  {"id":"dbu.mira.6fb61f9a","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"And they’ve got no oil. When the snow shuts the pass it’s six weeks of dark up there."},
  {"id":"dbu.mira.a4b1a2d6","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"You’ve just told a stranger exactly what you need. Either you’re honest or you’re new."},
  {"id":"dbu.mira.8142a031","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"You know how the line works? We each load at our own post, then we both haul. The baskets swap in the middle. Nobody sees what the other loaded until it’s on their side."},
  {"id":"dbu.hollis.207b42b2","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"And nobody takes anything back once it’s moving."},
  {"id":"dbu.storyteller.1ea2228b","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You fill a jar of lamp oil. It is heavy in a way that has nothing to do with weight: a full jar is a week of light for a hamlet you will never see."},
  {"id":"dbu.storyteller.f7bff620","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You could fill it to the neck. Or fill it halfway, wrap it so it doesn’t slosh, and keep the rest for a winter that is coming either way."},
  {"id":"dbu.storyteller.27d3d4c2","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"What goes in the basket?"},
  {"id":"dbu.storyteller.5e5a46f8","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You both haul. The basket shudders out over the drop, swings in the dark, and comes home."},
  {"id":"dbu.storyteller.dc610941","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Inside: a bundle of fever-bark, more than you’d hoped, tied with amber thread."},
  {"id":"dbu.storyteller.2f9a1641","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Across the gorge, Mira lifts your jar to her lantern. You watch her shoulders drop as she weighs it."},
  {"id":"dbu.mira.46e85263","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Full. You actually filled it."},
  {"id":"dbu.hollis.2148e5a3","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"And she actually sent it. Well. There’s a first time for everything on this river."},
  {"id":"dbu.storyteller.69ea1122","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Night four. The cold has a new edge. There is snow on the far peaks now, low enough to see by moonlight."},
  {"id":"dbu.mira.8e19b7fa","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I’ve been thinking about the line."},
  {"id":"dbu.mira.cc43fdfb","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"One cable, one basket, one jar a night. The pass shuts in two weeks. At this rate Orrin’s gets a few jars, your town gets a few bundles, and we all pretend that’s enough."},
  {"id":"dbu.mira.d98f8eb9","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"There’s timber on my side — planks from the old mill. With rope I could rig a second line. A walkway, eventually. A bridge, if we’re both stubborn."},
  {"id":"dbu.storyteller.c1e8fc8a","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Rope. You have three coils of good hemp, the last in town. If she has them, and decides she likes them better on her side, there is no more rope."},
  {"id":"dbu.mira.0fce6e47","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"We did this once and it worked. I’d like it to work every night until the snow. And then in spring. And then for as long as these two cliffs stay where they are."},
  {"id":"dbu.hollis.bef13323","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Thing is, it’s not one trade anymore. Whatever goes over tonight, she’ll remember every night after. So will you."},
  {"id":"dbu.storyteller.845ac6c9","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Three coils of rope. What do you send?"},
  {"id":"dbu.storyteller.95428818","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The basket comes back stacked with planks."},
  {"id":"dbu.mira.1143a3a9","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"All three? Then I’d better be good with knots."},
  {"id":"dbu.storyteller.fe58f49a","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"By midnight there is a second line across the Ashgill — a guide rope, taut and glistening. The basket rides steadier on it."},
  {"id":"dbu.storyteller.f059d7dc","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"It was never only tonight’s trade. Every basket was also a message about the next one."},
  {"id":"dbu.storyteller.82f8c4ca","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Night seven. By now the arrangement is simple, and spoken aloud: tonight you go first — oil and flour for Orrin’s Rest. Tomorrow she sends the big bundle. The Varn post came in. Real medicine, bark and salve, half of it for your side."},
  {"id":"dbu.storyteller.725cbf39","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Hollis’s leg is hot to the touch. He has stopped making jokes about it."},
  {"id":"dbu.storyteller.dd05c85e","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You load the basket. You haul. It crosses, and Mira takes it, and lifts her lantern once: thank you."},
  {"id":"dbu.storyteller.69e5f999","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The next night her lantern isn’t at the post. The basket comes back on its own."},
  {"id":"dbu.storyteller.d762103e","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"No bundle. No salve. Only a strip of oilcloth with charcoal letters on it."},
  {"id":"dbu.mira.8b59614f","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Fever at Orrin’s. Tav is sick. I took it all up the pass. I’m sorry. I’ll make it right."},
  {"id":"dbu.hollis.27521781","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Could be true."},
  {"id":"dbu.hollis.f114e40d","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Could be the oldest trick on this river. You can’t see up that mountain from here, and she knows it."},
  {"id":"dbu.hollis.41823037","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Either way, I’m not getting that salve."},
  {"id":"dbu.storyteller.e3683bc0","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You had an agreement. You kept your half first, because it was your turn to trust. Whatever her reasons were, she decided them without you."},
  {"id":"dbu.storyteller.eb2f69d9","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Night nine. Mira’s lantern is back at the far post. She doesn’t call across. She loads her side of the basket and waits."},
  {"id":"dbu.storyteller.f86f8340","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"It is your move. Whatever you send now is an answer."},
  {"id":"dbu.storyteller.41ea6536","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"How do you answer?"},
  {"id":"dbu.storyteller.51179ea3","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The baskets swap. Yours goes over empty. Hers comes back with a small clay pot of salve and a twist of bark — a third, maybe, of what she owed."},
  {"id":"dbu.storyteller.d4000d6c","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Across the gorge, Mira opens an empty basket. She doesn’t shout. She stands there with her lantern for a long time, and then she puts it out."},
  {"id":"dbu.hollis.1e81dafc","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Well. She’ll have felt that."},
  {"id":"dbu.hollis.cbea61a0","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Mind — she sent salve. Whatever else she is, she sent salve."},
  {"id":"dbu.storyteller.e92d075f","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Night ten. Her lantern again. She loads her side and waits, the way she always does."},
  {"id":"dbu.storyteller.6d52651e","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You know what she must be thinking. She sent salve, and got nothing."},
  {"id":"dbu.storyteller.0247d23c","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Her basket is loaded. Yours?"},
  {"id":"dbu.storyteller.bdf10eb8","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Your oil crosses. Her basket comes back empty — she is answering last night, not tonight."},
  {"id":"dbu.storyteller.d163cf88","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You send oil again the next night. This time her basket comes back with bark. Not much. A beginning."},
  {"id":"dbu.mira.f0ade242","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I thought you’d keep going. I would have."},
  {"id":"dbu.storyteller.fe9da2e1","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The echo didn’t stop because either of you was owed less. It stopped because someone went first."},
  {"id":"dbu.storyteller.7caff581","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Night thirteen. A storm off the high peaks — not like the one that took the bridge, but close enough that Hollis sits up when the shutters bang."},
  {"id":"dbu.storyteller.8334b021","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"There is a trade agreed for tonight, the last before the hard freeze: your oil, her bark."},
  {"id":"dbu.storyteller.81a4dc02","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"What do you load?"},
  {"id":"dbu.storyteller.0b1758a1","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You haul. Halfway over, the wind catches the basket and spins it hard. Something falls out of it into the dark. You can’t see what."},
  {"id":"dbu.storyteller.36d18029","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Her basket reaches you with the bark inside soaked through — black, ruined pulp. You can’t tell if it was ever any good."},
  {"id":"dbu.storyteller.467416b9","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Across the gorge, Mira holds your basket up to her lantern. Even from here, you can see that it’s empty."},
  {"id":"dbu.storyteller.40d5a403","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The signal lamp is by your hand. Shutters, a flame, the old keepers’ code. Short words only."},
  {"id":"dbu.storyteller.cecdaaa2","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"What do you signal?"},
  {"id":"dbu.storyteller.d7559fa4","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Two messages crossing in the dark, each one making the other’s basket make sense."},
  {"id":"dbu.storyteller.a4e866a1","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The signal didn’t change what the storm did. It changed what each of you believed the other had done."},
  {"id":"dbu.storyteller.8274dae5","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Night sixteen. Frost on the cable, white as bone. The pass will close any day now."},
  {"id":"dbu.mira.b28977b5","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"All the mill timber’s on my side. Your rope’s on yours. If we both walk out from the posts tomorrow, we could tie the last span in the middle. A real walkway. Before the snow."},
  {"id":"dbu.mira.c253e7ea","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"There’s one last load of Varn bark. I’ll trade it for the winter oil. Hollis’s leg, Tav’s fever. Same as always."},
  {"id":"dbu.hollis.b7467f46","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Your call. It’s always been your call — and hers."},
  {"id":"dbu.storyteller.aaee6ce6","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"What do you offer?"},
  {"id":"dbu.mira.43837860","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Tomorrow, then. Bring good rope."},
  {"id":"dbu.storyteller.3415cf06","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You walk out from your post as she walks out from hers, each of you on the other’s knots, and you tie the last span in the middle with the wind pulling at your coats."},
  {"id":"dbu.storyteller.cc948882","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The first snow comes three days later. By then there is a walkway across the Ashgill — narrow, swaying, planks lashed to hemp — with a lantern at each end."},
  {"id":"dbu.storyteller.7ca91521","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Mira crosses it first. She stops in the middle, where the baskets used to swap, looks down at the drop, and laughs."},
  {"id":"dbu.mira.ee97fde1","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"So you’re the one who’s been eating my bark."},
  {"id":"dbu.hollis.13009b75","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"And you’re the one who’s been burning our oil."},
  {"id":"dbu.storyteller.ccf5dff7","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Neither of you talks about the empty baskets. But both of you remember who stopped first."},
  {"id":"dbu.storyteller.2cd8b995","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The old cable still runs underneath. Nobody suggests taking it down."},
  {"id":"dbu.mira.23557d68","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Plank, rope, plank, rope. Nobody stands on faith."},
  {"id":"dbu.mira.b1a55348","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I like that better than faith, if I’m honest."},
  {"id":"dbu.storyteller.6e4a8d87","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"It goes up one plank at a time: her plank, your rope, her plank, your rope. Nobody has to stand on faith. By the end, nobody needs to."},
  {"id":"dbu.mira.c8732d58","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Tav had the fever. He was eleven hours from anyone who could help, and I had the bark in my pack."},
  {"id":"dbu.mira.3b3fd4b0","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I’d do it again. I want you to know that, so you don’t think I’m sorry for the wrong thing."},
  {"id":"dbu.mira.5e30a00e","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I’m sorry I decided it alone. I should have stood at that post and told you before, not left you a note after. You’d have been angry. But you’d have known."},
  {"id":"dbu.storyteller.d1cd7d9f","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Now that you’ve heard it — what do you offer?"},
  {"id":"dbu.mira.ef28148b","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Oil for bark, then. Like the first night."},
  {"id":"dbu.storyteller.48b19fcd","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You trade the oil for the bark across the old cable, the way you did the first night. No more, no less. It is enough to get both banks through."},
  {"id":"dbu.storyteller.3e36127e","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"When the snow comes, her lantern still appears at the post some nights. You still lift yours. The planks and the rope stay where they are, waiting for a spring that might want them."},
  {"id":"dbu.storyteller.a23b8fff","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The baskets swap. Hers brings you the last of the Varn bark. Yours brings her nothing."},
  {"id":"dbu.storyteller.36693f6c","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Across the gorge she lifts the empty basket, and you think of the night she did this to you, and you wait to feel even."},
  {"id":"dbu.mira.8ff4c5cb","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I suppose I taught you that."},
  {"id":"dbu.storyteller.7afd1beb","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Hollis’s leg heals. Orrin’s Rest gets through the winter on what Mira can carry over the high road, which is not much, and not enough, and it gets through anyway."},
  {"id":"dbu.storyteller.5ead06ab","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"In spring the guide line is gone, cut at her post. The old cable stays. Cables don’t care."},
  {"id":"dbu.storyteller.1880f0e6","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You are even now. It turns out even is a place two people can live, a long way apart."},
  {"id":"dbu.storyteller.2b04eb58","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You signal back: Storm. Same as yours."},
  {"id":"dbu.mira.197c84f4","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"You asked, the storm night too. Most people just decide what you meant."},
  {"id":"dbu.storyteller.579000ee","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You leave the lamp dark. Across the gorge her lantern stays at the post a while longer, and then goes."},
  {"id":"dbu.mira.abf1fc72","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"An empty basket, on a stormy night. Very convenient."},
  {"id":"dbu.storyteller.b6031b0b","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Neither of you could see the other side of the storm. Each of you filled in the blank with the other person’s worst night."},
  {"id":"dbu.mira.f51925d3","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I’m here because Orrin’s Rest still needs oil for the dark weeks. That’s all. I’m not walking out on anything you’ve tied."},
  {"id":"dbu.mira.4973024b","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Not this winter."},
  {"id":"dbu.storyteller.5eab5f09","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"But she doesn’t cut the line."},
  {"id":"dbu.storyteller.6f6bee05","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The oil and the last of the bark cross the old cable. No more than that."},
  {"id":"dbu.storyteller.536144b4","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Through the snow you can still see her lantern at the post, some nights. Some nights you blink yours. Once — only once — she blinks back."},
  {"id":"dbu.mira.1e0ee9a1","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Tav was sick. I chose him. That’s the whole of it."},
  {"id":"dbu.mira.556429b5","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"You want my reasons now, after all this? Fine. Those are my reasons."},
  {"id":"dbu.mira.ce06ecc1","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Suits me."},
  {"id":"dbu.storyteller.ad14f0ec","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You trade one last time without a word. Then the snow comes, and the line goes slack."},
  {"id":"dbu.storyteller.f1d05a7d","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Hollis’s leg heals, slowly, on what bark you managed to get. Orrin’s Rest gets through the winter on what Mira can carry over the high road."},
  {"id":"dbu.storyteller.fe0498d3","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Some nights you look across for her lantern. Some nights it’s there."},
  {"id":"dbu.storyteller.9c957844","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Then nothing. Her lantern goes out."},
  {"id":"dbu.mira.297de158","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"You looked at wet bark and decided it was me. And your basket was empty — and I’m supposed to believe that was the weather?"},
  {"id":"dbu.storyteller.3c0def79","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You know what was in it: less than you promised. Now there is nothing, and only you know it was ever less."},
  {"id":"dbu.mira.3f836058","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I’ve got timber. You’ve got rope. We could finish a walkway, maybe. I’ll be honest — I don’t know that I want to stand in the middle of the Ashgill on your knots."},
  {"id":"dbu.storyteller.328f1c7c","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"She doesn’t mention the storm night. She believed you about it."},
  {"id":"dbu.mira.a27f903a","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Together. On faith."},
  {"id":"dbu.storyteller.3f8b9d3f","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"She doesn’t say no. She doesn’t say yes."},
  {"id":"dbu.storyteller.a4fb721f","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You tie your end and walk out. Mira steps onto your rope as far as the first knot. Not the second."},
  {"id":"dbu.mira.7cfa927b","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Spring. Ask me again in spring."},
  {"id":"dbu.storyteller.b0f2d3a5","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The baskets keep crossing all winter. Every week she walks out one knot further, and back."},
  {"id":"dbu.storyteller.3aabf91a","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Once, on the walkway, she mentions the storm night — how glad she was you told her. You don’t correct her. It sits in you like a small stone in a boot: the kind you can walk on for years."},
  {"id":"dbu.storyteller.4e54a175","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You signal back: Storm. It is true, as far as it goes."},
  {"id":"dbu.storyteller.92887c96","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Both baskets cross empty."},
  {"id":"dbu.storyteller.98a88a09","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Night eleven: the same. Night twelve: the same. Neither of you could say any more whose turn it was to stop."},
  {"id":"dbu.storyteller.821591c1","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The guide line, which nobody is tending, starts to fray where it rubs the rock."},
  {"id":"dbu.hollis.538b34e4","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Two of you, punishing each other with nothing. It’s almost restful."},
  {"id":"dbu.storyteller.97628b71","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Each empty basket was an answer to the one before it. That is how it keeps going: everyone is only ever responding."},
  {"id":"dbu.storyteller.a835c92d","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"There has been no trade for days. But tonight a lantern blinks from the far post, in the keepers’ code: Try again?"},
  {"id":"dbu.storyteller.662248f7","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Just that. In her place, you might have said the same."},
  {"id":"dbu.storyteller.db47a00a","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The truth did cross the gorge. Whether it was believed depended on everything that had crossed before it."},
  {"id":"dbu.storyteller.96a141e3","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You don’t go to the post. From the window you watch her lantern wait."},
  {"id":"dbu.storyteller.e6061ff6","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Near midnight she hauls her side alone. The basket jerks out over the gorge, stops dead in the middle, and hangs there in the rain."},
  {"id":"dbu.storyteller.4046193f","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"In the morning you can see it from the town: a small dark shape over the drop, with something in it. When you finally haul it in, two nights later, the salve inside has gone to grey water."},
  {"id":"dbu.mira.dfdf7b98","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I didn’t know if you were sick, or angry, or gone. I sent what I had. It sat out there for two nights."},
  {"id":"dbu.storyteller.2ec12a6d","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Stepping back kept you safe from her. It also kept you from hearing what she had to say."},
  {"id":"dbu.storyteller.0440e4ea","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Something in the way she stands has changed. Not trust, exactly. Less guessing."},
  {"id":"dbu.storyteller.00ff0508","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"She never mentions the empty basket. The next night she sends half the usual bark, like someone checking."},
  {"id":"dbu.storyteller.69ba0cf0","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Your oil goes over. Hers comes back with a small clay pot of salve and a twist of bark — a third, maybe, of what she owed."},
  {"id":"dbu.mira.80980ffa","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"You sent it anyway."},
  {"id":"dbu.mira.50d99212","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Why?"},
  {"id":"dbu.storyteller.5c216c56","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"There isn’t an answer that fits across a gorge. You lift your lantern. After a moment, she lifts hers."},
  {"id":"dbu.hollis.f296b492","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Salve’s salve. I’ll take a third."},
  {"id":"dbu.hollis.38e818c5","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Mind you, she’s learned you’ll send whatever happens. Some people take that as a gift. Some take it as a policy."},
  {"id":"dbu.storyteller.7b7ff72c","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You gave her a way back without asking anything for it, and she took it. Whether that’s generosity or an invitation depends on who is on the other side."},
  {"id":"dbu.mira.a1b673b2","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Tomorrow. Bring rope."},
  {"id":"dbu.storyteller.7f6fb390","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Her planks come over short — two in every five missing. The walkway reaches a third of the way out from each side and stops."},
  {"id":"dbu.mira.85d7c267","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Councillor Dace kept back a share. He says the east will send whatever happens, so why pay full price."},
  {"id":"dbu.mira.8c3ef211","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I told him he was wrong about you. Prove me right. Next time, ask for the planks before you send the rope."},
  {"id":"dbu.storyteller.a0e0147e","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The baskets keep crossing all winter, on two lines instead of one. In spring, you think, you’ll ask for the planks first."},
  {"id":"dbu.storyteller.d2befc77","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Half the oil goes over, your note tied to the jar. Hers comes back with a small clay pot of salve and a twist of bark — a third, maybe, of what she owed."},
  {"id":"dbu.storyteller.a9b84ed5","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"She reads the note by her lantern."},
  {"id":"dbu.mira.aca33bc7","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Fair."},
  {"id":"dbu.mira.7c1da220","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"That’s fair. I’d have done the same, and been less polite about it."},
  {"id":"dbu.storyteller.31107c65","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Two nights later the rest of the salve comes over, wrapped twice. The rest of your oil goes the other way."},
  {"id":"dbu.hollis.261498fd","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"That’s not trust, exactly. It’s better. It’s a rule you can both see."},
  {"id":"dbu.storyteller.ee65071a","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Forgiving her didn’t mean letting it go. It meant leaving a door open — and saying exactly where it was."},
  {"id":"dbu.storyteller.04bdf0d1","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Some nights the old note is still tied to her post: The rest when the salve comes. She says she keeps it as a reminder of the night you both learned to say what you meant."},
  {"id":"dbu.storyteller.7dad6bd1","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"One coil goes over. A hand-line, Mira calls it — enough to steady the basket in a wind. Not enough to build on."},
  {"id":"dbu.mira.b8e36f7f","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"One coil. Fair enough. Trust by the coil."},
  {"id":"dbu.storyteller.6f35cbc1","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Oil goes over, and no rope. Mira looks for a long time at the space in the basket where rope would have been."},
  {"id":"dbu.mira.deb55a31","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Right."},
  {"id":"dbu.storyteller.09f3c60c","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Her planks sit stacked on your side now, and there is no rope on hers. Nobody can build anything with that."},
  {"id":"dbu.mira.229f97d7","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Fever at Orrin’s. Tav is sick. I took it all up the pass. You held back before. Now I have. We’re even."},
  {"id":"dbu.storyteller.4302f70b","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Inside: a generous bundle of fever-bark, tied with amber thread."},
  {"id":"dbu.storyteller.2f446a50","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Across the gorge, Mira lifts your jar and tips it toward the light. She holds it there a long moment."},
  {"id":"dbu.mira.be11ec5e","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Half."},
  {"id":"dbu.mira.b6509384","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"That’s — fine. You didn’t know me. I’ll remember that you didn’t know me."},
  {"id":"dbu.hollis.a11824d4","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"You got the better end of tonight. Mind it’s only tonight."},
  {"id":"dbu.mira.f34eb7c3","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I’ll be honest. After the half jar, I don’t know about you. So: one plank tonight. When your baskets are honest twice, the rest come over."},
  {"id":"dbu.storyteller.443ea531","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The basket comes back with a single plank, laid in it like a question."},
  {"id":"dbu.mira.1f17d410","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"…All three. All right. All right."},
  {"id":"dbu.storyteller.b5322c10","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The rest of her planks come over the next night, without being asked."},
  {"id":"dbu.mira.a145c12f","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"One coil for one plank. Aren’t we a pair."},
  {"id":"dbu.storyteller.4709717f","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Nothing new crosses the Ashgill."},
  {"id":"dbu.mira.de5a9b4d","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Careful. Good. So am I."},
  {"id":"dbu.mira.7f14aec3","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Bark, from the Varn road. Some of it could be yours. Depends what’s on your side."},
  {"id":"dbu.storyteller.7f50c039","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"You tell her: oil. She goes quiet for a moment, and you realise she wanted it more than she’s letting on."},
  {"id":"dbu.mira.e3f066a0","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Then we’re two careful people with a basket between us."},
  {"id":"dbu.storyteller.ab2c9aff","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Inside: a thin twist of bark. Enough for a day or two. Not a cure."},
  {"id":"dbu.storyteller.7ea5adef","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Across the gorge, Mira lifts your jar and goes still."},
  {"id":"dbu.mira.830df28a","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"…Full."},
  {"id":"dbu.mira.eebe8992","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I sent you a stranger’s share. I didn’t think you’d — I owe you for this one."},
  {"id":"dbu.hollis.e3b80a41","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"She took the better end tonight. Let’s see what she does with it."},
  {"id":"dbu.mira.e0ebe4e2","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"I owe you from the first night. So I’ll go first this time — the timber’s already on my post. Send what you think is fair."},
  {"id":"dbu.storyteller.32f356d3","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The basket comes back stacked with planks — and, wedged between them, a second bundle of bark."},
  {"id":"dbu.storyteller.81c3ad84","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Inside: a thin twist of bark. Across the gorge, Mira weighs a half-empty jar."},
  {"id":"dbu.mira.b70fe437","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"Well. We were both careful."},
  {"id":"dbu.storyteller.7dbf7622","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"Each of you kept back enough to be safe. Neither of you got enough to matter. Hollis’s leg needs more than a day of bark; Orrin’s Rest needs more than half a jar."},
  {"id":"dbu.hollis.9462a56c","lesson":"dbu","character":"hollis","style":"dialogue","sync":"spoken","text":"Safe’s a cold thing to sleep in."},
  {"id":"dbu.mira.1394db20","lesson":"dbu","character":"mira","style":"dialogue","sync":"spoken","text":"We’re both still holding back. I’m sending half the timber. Do what you like with that."},
  {"id":"dbu.storyteller.9c6ac050","lesson":"dbu","character":"storyteller","style":"narration","sync":"spoken","text":"The basket comes back with half a stack of planks."},
  {"id":"dbu.reflect.1","lesson":"dbu","character":"storyteller","style":"narration","sync":"computed","text":"Trust is not a promise that nothing will go wrong. It is something people build out of what they do, how they answer when something does go wrong, and whether they can find a way forward together."},
  {"id":"dbu.reflect.2","lesson":"dbu","character":"storyteller","style":"narration","sync":"computed","text":"Cooperating doesn’t mean ignoring harm. Forgiving doesn’t mean giving up your boundaries. And sometimes the difference between a broken arrangement and a repaired one starts with a message that makes the truth a little clearer."},
  {"id":"dbu.reflect.question","lesson":"dbu","character":"storyteller","style":"narration","sync":"computed","text":"What is one situation where you could make cooperation easier without giving up your boundaries?"},
  {"id":"mer.enter.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Under the dome, twelve plinths stand in a ring. On each one, a contestant has left a rule: a short instruction for what to do when it meets someone."},
  {"id":"mer.enter.2","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Every rule meets every other, one by one, for 50 rounds at a time. Each round both sides choose at the same moment — to share, or to take — and points are paid out. Then they choose again."},
  {"id":"mer.enter.3","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Whoever earns the most points across the whole hall wins the Trials."},
  {"id":"mer.enter.4","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"You have one plinth. What you put on it is up to you."},
  {"id":"mer.pick.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Three rules are already written. Pick one to place on your plinth."},
  {"id":"mer.single.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Before your rule plays, the stewards ask you to play one meeting yourself, against a stranger you will never see again."},
  {"id":"mer.single.took","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"They shared. You took. Five points to nothing — the best result there is, for you."},
  {"id":"mer.single.shared","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"They shared too. Three points each."},
  {"id":"mer.single.2","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Look at the table again. Whatever the stranger does, taking pays you more: 5 instead of 3 if they share, 1 instead of 0 if they take. In a single meeting, taking is the safe bet."},
  {"id":"mer.single.3","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Now add both sides together. If you both share, the pair makes 6. If you both follow the safe bet and take, the pair makes 2."},
  {"id":"mer.single.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"What is best for each of you alone leaves both of you worse off together."},
  {"id":"mer.single.name","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"This shape of situation has a name: the prisoner’s dilemma. Sharing is usually called cooperating; taking, defecting."},
  {"id":"mer.repeat.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"When you meet again, a move isn’t only a move. It’s what the other side will answer next round."},
  {"id":"mer.echo.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"In the practice hall, two Mirrors are paired. They should share forever. But in round 4, the first Mirror’s hand slips — it meant to share, and took."},
  {"id":"mer.echo.mirror","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Watch what the one slip does. Mirror B answers it — fairly. Mirror A answers that. Then B answers A. The defection bounces back and forth for the rest of the match, and neither of them ever chooses to stop."},
  {"id":"mer.echo.long-memory","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"The Long Memory never forgets a defection. One slip, and both sides take for the rest of the match — 23 points each where there could have been 42."},
  {"id":"mer.echo.patient","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"This partner waits for two defections in a row before hitting back. It lets the single slip pass, and the echo dies after one round."},
  {"id":"mer.echo.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Hitting back stops you from being used. It can also keep a fight going long after anyone remembers why it started."},
  {"id":"mer.trials.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Twelve rules: yours, and one of each kind the stewards could find. Everyone meets everyone, including a copy of itself. 50 rounds a match."},
  {"id":"mer.trials.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"A rule that never beats anyone can still come out on top — by doing well with everyone."},
  {"id":"mer.trials.tft","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"In 1980 the political scientist Robert Axelrod invited researchers to submit rules for a repeated prisoner’s dilemma tournament. Tit for Tat — cooperate first, then copy the other side’s last move — was one of the simplest entries, and it won. It won a second, larger tournament too."},
  {"id":"mer.rooms.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"The stewards open three more halls. Same rules, same table — different company. Try each, with any of the three starting rules."},
  {"id":"mer.rooms.friendly","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Mostly cooperators: four Open Hands, two Gentle Mirrors, a Long Memory, a Settler — and one Prober."},
  {"id":"mer.rooms.hostile","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Mostly defectors: five Iron Walls, two Probers, a Wary Mirror and a Pendulum."},
  {"id":"mer.rooms.noisy","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"A room of reciprocators — three Mirrors, two Gentle Mirrors, two Long Memories, a Settler, an Open Hand, a Prober and an Iron Wall — where 5% of moves come out as their opposite."},
  {"id":"mer.rooms.friendly.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"A room full of unconditional sharers is a feast for anyone willing to take."},
  {"id":"mer.rooms.hostile.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Forgiveness that never stops is a weakness in a room like this one."},
  {"id":"mer.rooms.noisy.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"When mistakes happen, a little forgiveness keeps one accident from becoming a feud."},
  {"id":"mer.population.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"One last experiment before your final entry. Suppose each season, rules that scored well are copied by more contestants, and rules that scored badly are abandoned. The hall fills up with whatever is working."},
  {"id":"mer.population.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"The room decides which rules do well — and the rules that do well remake the room."},
  {"id":"mer.design.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"The last trial runs your rule through every hall at once: the Open Trials, the Garden, the Iron Hall and the Fog. Build it however you like."},
  {"id":"mer.final.insight","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"“What’s the best strategy?” has no answer on its own. Best against whom, in what room, under which rules?"},
  {"id":"mer.reflect.1","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"You came looking for the best strategy."},
  {"id":"mer.reflect.2","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"But a strategy never plays alone. It meets other strategies, under particular rules, in a room that can change — and that its own success helps to change."},
  {"id":"mer.reflect.3","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Sometimes you gain more by shaping the conditions so that cooperating becomes worthwhile than by trying to outsmart everyone in the room."},
  {"id":"mer.reflect.question","lesson":"mer","character":"steward","style":"narration","sync":"computed","text":"Where could changing the structure of an interaction create a better outcome than simply trying to win it?"},
] as const;
